import { Offering } from './offering/entities/offeringPackage.entity.js';
import { InvoiceLineItems } from './invoice/entities/invoice.entity.js';
import { ReadSettingsResponseData } from './setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from './setting/dto/FreeDimensionOnInvoice.js';
import { OfferingType } from './offering/entities/OfferingType.js';
import { ValidBillingCycles } from './offering/dto/createOffering.dto.js';

const baseDim = (over: any) => ({
    dimensionId: 'd1',
    dimensionName: 'Dim One',
    usageIncrement: '1',
    rounding: 'round',
    aggregationInterval: 'hour',
    aggregationMethod: 'sum',
    paymentSchedule: 'arrear',
    consumptionUnit: { type: 'count', unit: 'count-based' },
    ...over,
});

const run = async (dim: any, usageValue: string, settings: any) => {
    const dimensions = [dim] as any;
    const offeringInstance = Offering.getInstance(
        {
            offeringId: 'o1',
            offeringName: 'Plan',
            offeringType: OfferingType.usage,
            billingCycle: ValidBillingCycles.monthly,
            dimensions,
            subscriptionPrice: 0,
        } as any,
        'cust',
        'biz',
        undefined,
        settings as ReadSettingsResponseData,
        undefined,
        undefined,
        undefined,
        [{ dimensionId: dim.dimensionId, usage: [{ value: usageValue, startTime: '', endTime: '' }] }] as any,
    );
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: new Date('2026-07-01T00:00:00Z'),
        endDate: new Date('2026-08-01T00:00:00Z'),
        lineItems,
        negative: false,
        businessID: 'biz',
        customerId: 'cust',
        customerService: undefined,
        dimensions,
        offeringInstance,
    });
    return lineItems.getLineItems();
};

const show = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show };
const hide = { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide };

describe('allowance and free dimension rules', () => {
    test('exhausted finite allowance with overage allowed charges the overage only', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 10, overageAllowed: 'true' }), '25', show))
            .toEqual([expect.objectContaining({ quantity: 15, unitCost: 2 })]);
    });
    test('unexhausted allowance charges nothing and carries no line', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 10, overageAllowed: 'true' }), '8', show))
            .toEqual([]);
    });
    test('allowance met exactly carries no line', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 10, overageAllowed: 'true' }), '10', show))
            .toEqual([]);
    });
    test('unlimited allowance carries no line', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 'inf', overageAllowed: 'true' }), '900', show))
            .toEqual([]);
    });
    test('overage forbidden carries no line', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 10, overageAllowed: 'false' }), '900', show))
            .toEqual([]);
        expect(await run(baseDim({ consumptionPrice: '2', usageEntitlement: 10 }), '900', show)).toEqual([]);
    });
    test('no allowance charges everything', async () => {
        expect(await run(baseDim({ consumptionPrice: '2' }), '900', show))
            .toEqual([expect.objectContaining({ quantity: 900, unitCost: 2 })]);
    });
    test('free dimension shown or hidden per settings', async () => {
        expect(await run(baseDim({ consumptionPrice: '0.00' }), '900', show))
            .toEqual([expect.objectContaining({ quantity: 900, unitCost: 0 })]);
        expect(await run(baseDim({ consumptionPrice: '0.00' }), '900', hide)).toEqual([]);
        expect(await run(baseDim({ consumptionPrice: '0.00' }), '900', undefined))
            .toEqual([expect.objectContaining({ quantity: 900, unitCost: 0 })]);
    });
    test('allowance-only dimension without a price is free', async () => {
        expect(await run(baseDim({ usageEntitlement: 10 }), '900', show))
            .toEqual([expect.objectContaining({ unitCost: 0 })]);
        expect(await run(baseDim({ usageEntitlement: 10 }), '900', hide)).toEqual([]);
    });
    test('usage increment applies to the chargeable overage', async () => {
        expect(await run(baseDim({ consumptionPrice: '2', usageIncrement: '10', usageEntitlement: 100, overageAllowed: 'true' }), '2000', show))
            .toEqual([expect.objectContaining({ quantity: 190, unitCost: 2 })]);
    });
    test('priced dimension with no usage carries no line', async () => {
        expect(await run(baseDim({ consumptionPrice: '2' }), '0', show)).toEqual([]);
    });
});
